   <label><b>行李（可多尺寸）</b><input list="luggage-sizes" value={data.luggage} onChange={e=>setData({...data,luggage:e.target.value})} placeholder="例如：28吋 × 2｜胖胖箱 × 1" style={inp}/><datalist id="luggage-sizes">{sizes.map(x=><option key={x} value={x}/>)}</datalist></label>
   {field("carryOn","手提行李（件數）","number")}{field("vehicle","車型")}{field("amount","金額","number")}
